const crypto = require('crypto');
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};
const eventId = String(body.event_id || '');
const code = String(body.code || '').trim().toUpperCase();
let tel = String(body.tel || '').replace(/[^0-9]/g, '');
if (tel.startsWith('00')) tel = tel.slice(2);
if (tel.startsWith('0') && tel.length === 10) tel = '212' + tel.slice(1);
if (!tel.startsWith('212') && tel.length === 9) tel = '212' + tel;
const timestamp = String(headers['x-tuc-timestamp'] || '');
const signature = String(headers['x-tuc-signature'] || '').toLowerCase();
if (!/^[A-Za-z0-9._:-]{1,128}$/.test(eventId) || !/^[A-Z0-9]{8}$/.test(code) || !/^[1-9][0-9]{7,14}$/.test(tel)) throw new Error('Invalid WhatsApp event fields');
if (!/^[0-9]{10}$/.test(timestamp) || Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) throw new Error('Expired WhatsApp event');
const canonical = [timestamp, eventId, code, tel].join('\n');
const expected = crypto.createHmac('sha256', $env.TUC_N8N_INBOUND_SECRET).update(canonical).digest('hex');
if (!/^[a-f0-9]{64}$/.test(signature) || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) throw new Error('Invalid inbound HMAC');
const wpTimestamp = String(Math.floor(Date.now() / 1000));
const wpCanonical = [wpTimestamp, eventId, code, tel].join('\n');
const wpSignature = crypto.createHmac('sha256', $env.TUC_WA_SECRET).update(wpCanonical).digest('hex');
return [{ json: { eventId, code, tel, timestamp: wpTimestamp, signature: wpSignature, payload: { code, tel } } }];
